  package   org . simmetrics . metrics ;   import static      com . google . common . base . Preconditions . checkArgument ;  import static      com . google . common . base . Strings . commonPrefix ;  import static    java . lang . Math . min ;  import   org . simmetrics . StringMetric ;  import   org . simmetrics . StringDistance ;   public final class JaroWinkler  implements  StringMetric , StringDistance  {   private final Jaro  jaro =  new Jaro  ( ) ;   private static final  float  PREFIX_SCALE = 0.1f ;   private static final  float  WINKLER_BOOST_THRESHOLD = 0.7f ;   private static final  float  BOOST_THRESHOLD = 0.0f ;   private static final  int  MAX_PREFIX_LENGTH = 4 ;   private final  float  boostThreshold ;   private final  float  prefixScale ;   private final  int  maxPrefixLength ;   public JaroWinkler  ( )  {  this  ( BOOST_THRESHOLD , PREFIX_SCALE , MAX_PREFIX_LENGTH ) ; }   public static JaroWinkler createWithBoostThreshold  ( )  {  return  new JaroWinkler  ( WINKLER_BOOST_THRESHOLD , PREFIX_SCALE , MAX_PREFIX_LENGTH ) ; }   public JaroWinkler  (   float boostThreshold ,   float prefixScale ,   int maxPrefixLength )  {   checkArgument  (  boostThreshold >= 0 ) ;   checkArgument  (   0 <= prefixScale &&  prefixScale <= 1 ) ;   checkArgument  (  maxPrefixLength >= 0 ) ;    this . boostThreshold = boostThreshold ;    this . prefixScale = prefixScale ;    this . maxPrefixLength = maxPrefixLength ; }    @ Override public  float compare  (   final String a ,   final String b )  {   final  float  jaroScore =  jaro . compare  ( a , b ) ;  if  (  jaroScore < boostThreshold )  {  return jaroScore ; }   int  prefixLength =  min  (   commonPrefix  ( a , b ) . length  ( ) , maxPrefixLength ) ;  return  jaroScore +  (   prefixLength * prefixScale *  (  1.0f - jaroScore ) ) ; }    @ Override public String toString  ( )  {  return       "JaroWinkler [boostThreshold=" + boostThreshold + ", prefixScale=" + prefixScale + ", maxPrefixLength=" + maxPrefixLength + "]" ; }    @ Override public  float distance  (  String a ,  String b )  {  return  1.0f -  compare  ( a , b ) ; } }